/// Immutable, source-coherent scene graph suitable for worker ownership transfer.
#[derive(Debug)]
pub struct SceneGraph {
    pub(crate) owner: u64,
    pub(crate) source: SourceOwner,
    pub(crate) generation: u64,
    pub(crate) root: SceneId,
    pub(crate) scenes: Vec<SceneData>,
    pub(crate) animation: OwnedAnimation,
    pub(crate) ignored: [Ignored; 4],
    pub(crate) stats: MemoryStats,
}
impl SceneGraph {
    pub fn scene_id(&self, index: usize) -> Option<SceneId> {
        let scene = self.scenes.get(index)?;
        Some(SceneId {
            owner: self.owner,
            slot: u32::try_from(index).ok()?,
            serial: scene.serial,
        })
    }
    pub fn source_owner(&self) -> &SourceOwner {
        &self.source
    }
    pub fn source(&self) -> &[u8] {
        self.source.as_slice()
    }
    pub fn generation(&self) -> u64 {
        self.generation
    }
    pub fn root(&self) -> SceneView<'_> {
        self.scene(self.root).expect("validated root")
    }
    pub fn scene(&self, id: SceneId) -> Option<SceneView<'_>> {
        let scene = self.scenes.get(id.index())?;
        if id.owner != self.owner || id.serial != scene.serial {
            return None;
        }
        Some(scene.view(
            self.owner,
            id.index(),
            &self.scenes,
            &self.source,
            self.animation.view(),
            self.ignored,
        ))
    }
    pub fn scene_count(&self) -> usize {
        self.scenes.len()
    }
    pub fn animation(&self) -> AnimationView<'_> {
        self.animation.view()
    }
    pub fn ignored(&self, kind: IgnoredKind) -> Ignored {
        self.ignored[kind as usize]
    }
    pub fn memory_stats(&self) -> MemoryStats {
        self.stats
    }
}
use crate::{Diagnostic, ErrorKind, LimitKind, Result};
/// Vec-reported reserved storage, excluding allocator bookkeeping and RSS.
/// Allocation history describes builder reserves and admitted owned payloads;
/// it does not reconstruct allocation calls made by parsers/providers before admission.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct MemoryStats {
    pub source_bytes: usize,
    pub live_bytes: usize,
    pub peak_live_bytes: usize,
    pub total_allocated_bytes: usize,
    pub allocation_count: usize,
}
pub(crate) fn bytes<T>(values: &Vec<T>) -> Result<usize> {
    values
        .capacity()
        .checked_mul(std::mem::size_of::<T>())
        .ok_or_else(arithmetic)
}
pub(crate) fn add(a: usize, b: usize) -> Result<usize> {
    a.checked_add(b).ok_or_else(arithmetic)
}
pub(crate) fn arithmetic() -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::Limit(LimitKind::Arithmetic),
        offset: 0,
    }
}
/// Reserve a replacement before transferring old values. Reject excess actual
/// capacity before moving anything. The caller supplies the available overlap budget.
pub(crate) fn reserve<T>(
    values: &mut Vec<T>,
    extra: usize,
    cap: usize,
    overlap: usize,
) -> Result<(usize, usize)> {
    let required = values.len().checked_add(extra).ok_or_else(arithmetic)?;
    if required > cap {
        return Err(Diagnostic {
            kind: ErrorKind::Limit(LimitKind::Nodes),
            offset: 0,
        });
    }
    if required <= values.capacity() {
        return Ok((0, 0));
    }
    let request = required
        .checked_mul(std::mem::size_of::<T>())
        .ok_or_else(arithmetic)?;
    if request > overlap {
        return Err(Diagnostic {
            kind: ErrorKind::Limit(LimitKind::ReservedBytes),
            offset: 0,
        });
    }
    let mut replacement = Vec::new();
    let grown = values
        .capacity()
        .checked_mul(2)
        .unwrap_or(cap)
        .max(8)
        .min(cap)
        .max(required);
    let target = if grown
        .checked_mul(std::mem::size_of::<T>())
        .is_some_and(|n| n <= overlap)
    {
        grown
    } else {
        required
    };
    replacement
        .try_reserve_exact(target)
        .map_err(|_| Diagnostic {
            kind: ErrorKind::OutOfMemory,
            offset: 0,
        })?;
    let actual = bytes(&replacement)?;
    if actual > overlap {
        return Err(Diagnostic {
            kind: ErrorKind::Limit(LimitKind::ReservedBytes),
            offset: 0,
        });
    }
    let old = bytes(values)?;
    replacement.append(values);
    *values = replacement;
    Ok((actual, old))
}

