#[derive(Debug)]
pub struct EvaluatedFrame<'a> {
    base: SceneView<'a>,
    byte_limit: usize,
    edges: Option<Vec<Edge>>,
    colors: Option<Vec<[u8; 4]>>,
    shapes: Option<Vec<Shape>>,
    fill_paints: Option<Vec<Paint>>,
    stroke_paints: Option<Vec<Paint>>,
    transforms: Option<Vec<TransformFrame>>,
    clips: Option<Vec<Clip>>,
    stats: MemoryStats,
}
#[derive(Debug)]
pub struct FrameBuilder<'a> {
    frame: EvaluatedFrame<'a>,
    byte_limit: usize,
}
impl<'a> EvaluatedFrame<'a> {
    pub fn view(&self) -> SceneView<'_> {
        self.base.overlay(
            self.edges.as_deref(),
            self.colors.as_deref(),
            self.shapes.as_deref(),
            self.fill_paints.as_deref(),
            self.stroke_paints.as_deref(),
            self.transforms.as_deref(),
            self.clips.as_deref(),
        )
    }
    pub fn base(&self) -> SceneView<'a> {
        self.base
    }
    pub fn memory_stats(&self) -> MemoryStats {
        self.stats
    }
    /// Publish a complete clip update only after validating every replacement.
    /// Old owned clips remain live during validation and admission; the original
    /// configured frame budget includes that overlap. Base data never changes.
    pub fn replace_clips(
        &mut self,
        values: Vec<Clip>,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        control.checkpoint().map_err(stopped)?;
        if values.len() != self.base.clips.len() {
            return Err(invalid(0));
        }
        let view = self.view();
        for (index, clip) in values.iter().enumerate() {
            control.charge(WorkKind::ClipChild, 1).map_err(stopped)?;
            if clip.parent != self.base.clips[index].parent {
                return Err(invalid(0));
            }
            crate::validate::clip_view(view, clip, control)?;
        }
        let new = clip_bytes(&values, control)?;
        if new > 64 * 1024 * 1024 {
            return Err(limit(LimitKind::Animation));
        }
        let old = if let Some(clips) = &self.clips {
            clip_bytes(clips, control)?
        } else {
            0
        };
        let overlap = add(self.stats.live_bytes, new)?;
        if overlap > self.byte_limit {
            return Err(limit(LimitKind::ReservedBytes));
        }
        let live = add(
            self.stats
                .live_bytes
                .checked_sub(old)
                .ok_or_else(arithmetic)?,
            new,
        )?;
        let history = add(self.stats.total_allocated_bytes, new)?;
        let allocations = self
            .stats
            .allocation_count
            .checked_add(usize::from(new != 0))
            .ok_or_else(arithmetic)?;
        control.checkpoint().map_err(stopped)?;
        self.clips = Some(values);
        self.stats.live_bytes = live;
        self.stats.peak_live_bytes = self.stats.peak_live_bytes.max(overlap);
        self.stats.total_allocated_bytes = history;
        self.stats.allocation_count = allocations;
        Ok(())
    }
}
